package org.firstinspires.ftc.teamcode.opmodes.auto.generated;

import com.pedropathing.api.Paths;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.ivy.Command;
import com.pedropathing.math.Pose;
import com.pedropathing.paths.Path;

import org.firstinspires.ftc.teamcode.autokit.AutoKit;
import org.firstinspires.ftc.teamcode.autokit.AutoOption;

/**
 * Generated by the Auto Builder from red-garden-basic.pp. Do not edit: change the .pp and export again.
 */
public final class RedGardenBasicAuto {

    private RedGardenBasicAuto() {}

    /** The .pp file this was generated from. */
    public static final String SOURCE = "red-garden-basic.pp";

    /** When the .pp was saved, Michigan time (empty if unknown); the OpMode's name on the Driver Station ends with it. */
    public static final String SAVED = "";

    /** Registered robot commands this Auto uses; checked when the OpMode initialises. */
    public static final String[] COMMANDS = {"LaunchAll"};

    /** Registered robot triggers this Auto uses; checked when the OpMode initialises. */
    public static final String[] TRIGGERS = {"IntakeFull", "Tip"};

    /** The alliance the Auto was drawn for ("RED" or "BLUE"); the other alliance runs it rotated half a turn about the field centre. */
    public static final String DRAWN_FOR = "RED";

    /** What the drive team may change during INIT, on gamepad 1's D-pad; nothing changed, the Auto runs as drawn. */
    public static final AutoOption[] OPTIONS = {};

    /** Where the robot starts, for the given alliance. */
    public static Pose startPose(boolean rotated) {
        return poses(rotated).of(60, 9, 90);
    }

    private static PoseFactory poses(boolean rotated) {
        return rotated ? PoseFactory.degrees().mirrorAroundPoint(70.75, 70.75) : PoseFactory.degrees();
    }

    /** Builds the whole Auto. Call once, at init; schedule the result at start. */
    public static Command build(AutoKit kit, boolean rotated) {
        PoseFactory p = poses(rotated);

        // Named points (x, y in inches, heading in degrees, Pedro field frame).
        Pose start = p.of(60, 9, 90);
        Pose collectAhead = p.of(60.8, 29.5, 90);
        Pose collectLeft = p.of(50.1, 29.1, 117);
        Pose rearShot = p.of(60, 118.8, 90);
        Pose loadingFlower = p.of(47, 129.8, 90);
        Pose park = p.of(16, 106, 90);
        Pose collectHome = p.of(60, 10, 90);

        // Paths, written as the stock Visualizer export writes them.
        Path pass1Ahead = Paths.line(start, collectAhead).constant(collectAhead);
        Path collectAheadPark = Paths.line(collectAhead, park).constant(park);
        Path pass1Back = Paths.line(collectAhead, collectHome).constant(collectHome);
        Path collectHomePark = Paths.line(collectHome, park).constant(park);
        Path pass2Left = Paths.line(collectHome, collectLeft).linear(collectHome, collectLeft);
        Path collectLeftPark = Paths.line(collectLeft, park).linear(collectLeft, park);
        Path pass2Back = Paths.line(collectLeft, collectHome).linear(collectLeft, collectHome);
        Path toRearShot = Paths.line(collectHome, rearShot).constant(rearShot);
        Path rearShotPark = Paths.line(rearShot, park).constant(park);
        Path toLoadingFlower = Paths.line(rearShot, loadingFlower).constant(loadingFlower);
        Path toPark = Paths.line(loadingFlower, park).constant(park);

        return kit.sequence(
                kit.command("LaunchAll"),
                kit.firstOf("Did our HIVE tip?",
                        kit.when("Tip").then(
                                kit.guarded("If tipped", toPark, 1.7,
                                        kit.path("Pass1Ahead", pass1Ahead, 1.3, collectAheadPark, 2.6),
                                        kit.path("Pass1Back", pass1Back, 1.2, collectHomePark, 2.9),
                                        kit.path("Pass2Left", pass2Left, 1.3, collectLeftPark, 2.5),
                                        kit.path("Pass2Back", pass2Back, 1.3, collectHomePark, 2.9),
                                        kit.path("ToRearShot", toRearShot, 3, rearShotPark, 1.9),
                                        kit.command("LaunchAll"),
                                        kit.path("ToLoadingFlower", toLoadingFlower, 1.2),
                                        kit.firstOf("Take 4 POLLEN from the LOADING FLOWER",
                                                kit.when("IntakeFull"),
                                                kit.afterMs(1500)),
                                        kit.command("LaunchAll"),
                                        kit.path("ToPark", toPark, 1.7))),
                        kit.afterMs(8000).then(
                                kit.guarded("If not tipped", toPark, 1.7,
                                        kit.path("ToRearShot", toRearShot, 3, rearShotPark, 1.9),
                                        kit.path("ToLoadingFlower", toLoadingFlower, 1.2),
                                        kit.firstOf("Take 4 POLLEN from the LOADING FLOWER",
                                                kit.when("IntakeFull"),
                                                kit.afterMs(1500)),
                                        kit.command("LaunchAll"),
                                        kit.path("ToPark", toPark, 1.7)))));
    }
}
